private theorem PVM.integral_one (E_pvm : PVM E) :
    E_pvm.integral (fun _ : ℝ => (1 : ℂ)) measurable_const
      ⟨1, fun _ => by rw [norm_one]⟩ = 1

private theorem PVM.integral_const (E_pvm : PVM E) (z : ℂ) :
    E_pvm.integral (fun _ : ℝ => z) measurable_const
      ⟨‖z‖, fun _ => le_refl _⟩ = z • 1

private theorem generator_domain_invariant (U : StrongContUnitary E)
    (s : ℝ) (x : U.generator.domain) :
    U.toFun s (x : E) ∈ U.generator.domain

private theorem tendsto_phaseGroup_apply
    (U : StrongContUnitary E) {α : Type*} {l : Filter α}
    {t : α → ℝ} {t₀ : ℝ} {y : α → E} {y₀ : E}
    (ht : Tendsto t l (nhds t₀)) (hy : Tendsto y l (nhds y₀)) :
    Tendsto (fun a => U.toFun (t a) (y a)) l (nhds (U.toFun t₀ y₀))

private theorem inner_proj (E_pvm : PVM E) (x : E) (S : Set ℝ)
    (hS : MeasurableSet S) :
    @inner ℂ E _ x (E_pvm.proj S x) =
      (E_pvm.scalarContent x S : ℂ)

private theorem inner_proj_left (E_pvm : PVM E) (x : E) (S : Set ℝ)
    (hS : MeasurableSet S) :
    @inner ℂ E _ (E_pvm.proj S x) x =
      (E_pvm.scalarContent x S : ℂ)

private theorem inner_phaseUnitaryGroup (E_pvm : PVM E) (x : E) (t : ℝ) :
    @inner ℂ E _ x (E_pvm.phaseUnitaryGroup.toFun t x) =
      charFun (E_pvm.scalarMeasure x) t

private theorem scalarMeasure_eq_of_phaseGroup_eq (E₁ E₂ : PVM E)
    (hgroup : E₁.phaseUnitaryGroup = E₂.phaseUnitaryGroup) (x : E) :
    E₁.scalarMeasure x = E₂.scalarMeasure x

private theorem initialUnion_disjoint_tailUnion {X : Type*}
    (S : ℕ → Set X) (hpair : Pairwise fun i j => Disjoint (S i) (S j)) (n : ℕ) :
    Disjoint (initialUnion S n) (tailUnion S n)

private theorem iUnion_eq_initialUnion_union_tailUnion {X : Type*}
    (S : ℕ → Set X) (n : ℕ) :
    (⋃ i, S i) = initialUnion S n ∪ tailUnion S n

private theorem distanceToOneSq_ofReal (U : E →L[ℂ] E)
    (z : spectrum ℂ U) :
    ((distanceToOneSq U z : ℝ) : ℂ) = distanceToOneSqComplex U z

private theorem cayleyCoordinate_relation (t : ℝ) :
    (t : ℂ) * (1 - cayleyCoordinate t) =
      Complex.I * (1 + cayleyCoordinate t)

private theorem realPolarization_add_sub (x z y : V) :
    realPolarization q (x + z) y + realPolarization q (x - z) y =
      2 * realPolarization q x y

private theorem realPolarization_add_left (x z y : V) :
    realPolarization q (x + z) y =
      realPolarization q x y + realPolarization q z y

private theorem realPolarization_add_right (x y z : V) :
    realPolarization q x (y + z) =
      realPolarization q x y + realPolarization q x z

private theorem realPolarization_rat_smul_left (r : ℚ) (x y : V) :
    realPolarization q (((r : ℝ) : ℂ) • x) y =
      (r : ℝ) * realPolarization q x y

