private theorem realPolarization_I_I (x y : V) :
    realPolarization q (Complex.I • x) (Complex.I • y) =
      realPolarization q x y

private theorem realPolarization_I_left (x y : V) :
    realPolarization q (Complex.I • x) y =
      -realPolarization q x (Complex.I • y)

private theorem complexPolarization_add_left (x z y : V) :
    complexPolarization q (x + z) y =
      complexPolarization q x y + complexPolarization q z y

private theorem complexPolarization_add_right (x y z : V) :
    complexPolarization q x (y + z) =
      complexPolarization q x y + complexPolarization q x z

private theorem complexPolarization_I_left (x y : V) :
    complexPolarization q (Complex.I • x) y =
      star Complex.I * complexPolarization q x y

private theorem complexPolarization_I_right (x y : V) :
    complexPolarization q x (Complex.I • y) =
      Complex.I * complexPolarization q x y

private theorem complexPolarization_real_smul_left (r : ℝ) (x y : V) :
    complexPolarization q (r • x) y =
      (r : ℂ) * complexPolarization q x y

private theorem complexPolarization_real_smul_right (r : ℝ) (x y : V) :
    complexPolarization q x (r • y) =
      (r : ℂ) * complexPolarization q x y

private theorem complexPolarization_smul_left (c : ℂ) (x y : V) :
    complexPolarization q (c • x) y =
      star c * complexPolarization q x y

private theorem complexPolarization_smul_right (c : ℂ) (x y : V) :
    complexPolarization q x (c • y) =
      c * complexPolarization q x y

private theorem plusI_norm_sq (A : E →ₗ.[ℂ] E) (hA : IsSelfAdjoint A)
    (x : A.domain) :
    ‖plusI A x‖ ^ 2 = ‖A x‖ ^ 2 + ‖(x : E)‖ ^ 2

private theorem minusI_norm_sq (A : E →ₗ.[ℂ] E) (hA : IsSelfAdjoint A)
    (x : A.domain) :
    ‖minusI A x‖ ^ 2 = ‖A x‖ ^ 2 + ‖(x : E)‖ ^ 2

private theorem generator_domain_invariant (U : StrongContUnitary E)
    (s : ℝ) (x : U.generator.domain) :
    U.toFun s (x : E) ∈ U.generator.domain

private theorem integral_toFun_mem_generator_domain (U : StrongContUnitary E)
    (x : E) (a : ℝ) :
    (∫ t in 0..a, U.toFun t x) ∈ U.generator.domain

private theorem generator_add_I_surjective (U : StrongContUnitary E) :
    Function.Surjective
      (fun y : U.generator.domain ↦ U.generator y + Complex.I • (y : E))

private theorem generator_sub_I_surjective (U : StrongContUnitary E) :
    Function.Surjective
      (fun y : U.generator.domain ↦ U.generator y - Complex.I • (y : E))

private theorem differenceQuotient_add (U : StrongContUnitary E) (x y : E) :
    differenceQuotient U (x + y) =
      differenceQuotient U x + differenceQuotient U y

private theorem PVM.integral_one_local (E_pvm : PVM E) :
    E_pvm.integral (fun _ : ℝ => (1 : ℂ)) measurable_const
      ⟨1, fun _ => by rw [norm_one]⟩ = 1

private theorem PVM.integral_const_local (E_pvm : PVM E) (z : ℂ) :
    E_pvm.integral (fun _ : ℝ => z) measurable_const
      ⟨‖z‖, fun _ => le_refl _⟩ = z • 1

private theorem spectralEvolution_add (E_pvm : PVM E) (s t : ℝ) :
    spectralEvolution E_pvm (s + t) =
      spectralEvolution E_pvm s * spectralEvolution E_pvm t

private theorem stoneQuotient_tendsto (r : ℝ) :
    Tendsto (fun t : ℝ => stoneQuotient t r)
      (nhdsWithin 0 {0}ᶜ) (nhds (r : ℂ))

private theorem phaseGenerator_coordinate_integrable (E_pvm : PVM E)
    (x : (spectralUnitaryGroup E_pvm).generator.domain) :
    ∫⁻ r, ‖(r : ℂ)‖₊ ^ 2 ∂(E_pvm.scalarMeasure (x : E)) < ⊤

theorem PVM.sum_proj_preimage (E_pvm : PVM E) {β : Type*}
    (f : SimpleFunc ℝ β) (s : Finset β) :
    ∑ y ∈ s, E_pvm.proj (f ⁻¹' {y}) = E_pvm.proj (f ⁻¹' (↑s : Set β))

theorem PVM.norm_simpleIntegral_sub_le (E_pvm : PVM E) (f g : SimpleFunc ℝ ℂ) {C : ℝ}
    (hbdd : ∀ t, ‖f t - g t‖ ≤ C) :
    ‖E_pvm.simpleIntegral f - E_pvm.simpleIntegral g‖ ≤ C

private theorem nearestError_tendsto_of_nearestPt_tendsto (e : ℕ → ℂ) (z : ℂ)
    (h : Filter.Tendsto (fun n => SimpleFunc.nearestPt e n z) Filter.atTop (nhds z)) :
    Filter.Tendsto (fun n => nearestError e n z) Filter.atTop (nhds 0)

private theorem boundedApprox_mem (f : ℝ → ℂ) (hf : Measurable f)
    (C : ℝ) (hbdd : ∀ t, ‖f t‖ ≤ C) (n : ℕ) (t : ℝ) :
    boundedApprox f hf C hbdd n t ∈ Metric.closedBall (0 : ℂ) C

private theorem boundedApprox_norm_le (f : ℝ → ℂ) (hf : Measurable f)
    (C : ℝ) (hbdd : ∀ t, ‖f t‖ ≤ C) (n : ℕ) (t : ℝ) :
    ‖boundedApprox f hf C hbdd n t‖ ≤ C

private theorem boundedApprox_tendstoUniformly (f : ℝ → ℂ) (hf : Measurable f)
    (C : ℝ) (hbdd : ∀ t, ‖f t‖ ≤ C) :
    TendstoUniformly (fun n t => boundedApprox f hf C hbdd n t) f Filter.atTop

private theorem simpleIntegral_boundedApprox_cauchy (E_pvm : PVM E)
    (f : ℝ → ℂ) (hf : Measurable f) (C : ℝ) (hbdd : ∀ t, ‖f t‖ ≤ C) :
    CauchySeq (fun n => E_pvm.simpleIntegral (boundedApprox f hf C hbdd n))

private theorem PVM.spectralTruncation_tendsto (f : ℝ → ℂ) (t : ℝ) :
    Filter.Tendsto (fun n => PVM.spectralTruncation f n t)
      Filter.atTop (nhds (f t))

private theorem PVM.norm_spectralTruncation_sub_le (f : ℝ → ℂ)
    (n m : ℕ) (t : ℝ) :
    ‖PVM.spectralTruncation f m t - PVM.spectralTruncation f n t‖ ≤ m + n

private theorem PVM.spectralTruncation_error_measurable (f : ℝ → ℂ)
    (hf : Measurable f) (n : ℕ) :
    Measurable (fun t => (↑(‖f t - PVM.spectralTruncation f n t‖₊ ^ 2) : ENNReal))

private theorem PVM.spectralTruncation_error_le (f : ℝ → ℂ) (n : ℕ) (t : ℝ) :
    (↑(‖f t - PVM.spectralTruncation f n t‖₊ ^ 2) : ENNReal) ≤
      ↑(‖f t‖₊ ^ 2)

private theorem PVM.cauchySeq_truncatedIntegral (E_pvm : PVM E)
    (f : ℝ → ℂ) (hf : Measurable f) (x : E_pvm.squareIntegrableDomain f) :
    CauchySeq (fun n => E_pvm.truncatedIntegral f hf n (x : E))

private theorem PVM.integral_const_for_symmetry (E_pvm : PVM E) (z : ℂ) :
    E_pvm.integral (fun _ : ℝ => z) measurable_const
      ⟨‖z‖, fun _ => le_refl _⟩ = z • 1

theorem PVM.monotone (E_pvm : PVM E) {S T : Set ℝ}
    (hS : MeasurableSet S) (hT : MeasurableSet T) (h : S ⊆ T) (x : E) :
    (@inner ℂ E _ (E_pvm.proj S x) x).re ≤ (@inner ℂ E _ (E_pvm.proj T x) x).re

theorem PVM.proj_union (E_pvm : PVM E) {S T : Set ℝ}
    (hS : MeasurableSet S) (hT : MeasurableSet T) (hdisj : Disjoint S T) :
    E_pvm.proj (S ∪ T) = E_pvm.proj S + E_pvm.proj T
